// Sobol reference points from QuantLib's SobolRsg with the Joe-Kuo D6
// direction numbers (new-joe-kuo-6.21201), Gray-code order, for
// tests/fixtures/sobol.sexp. QuantLib's draw k is point k + 1 (it skips 0).
//
// Contents: (:dimensions 1111 :points 1000
//            :hashes (h_0 ... h_1110)        per dimension d, h = fold over
//                                            points i of (h * 1000003 + x_i)
//                                            mod 2^61 - 1, x_i the 32-bit integer
//            :first-points ((x ...) ...)     every dimension of the first 16 points
//            :first-dimensions ((x ...) ...)) all 1000 points of dimensions 0-7
#include <ql/math/randomnumbers/sobolrsg.hpp>
#include <cstdint>
#include <fstream>
#include <vector>

using namespace QuantLib;

int main(int, char** argv) {
    const Size dimensions = 1111, points = 1000;
    SobolRsg rsg(dimensions, 0, SobolRsg::JoeKuoD6);
    const std::uint64_t p = (std::uint64_t(1) << 61) - 1;
    std::vector<std::uint64_t> hash(dimensions, 0);
    std::vector<std::vector<std::uint32_t>> rows;
    for (Size i = 0; i < points; ++i) {
        const auto& x = rsg.nextInt32Sequence();
        rows.push_back(x);
        for (Size d = 0; d < dimensions; ++d)
            hash[d] = std::uint64_t(((unsigned __int128)hash[d] * 1000003 + x[d]) % p);
    }
    std::ofstream out(argv[1]);
    out << ";;;; Generated by tests/fixtures/generate_sobol.cpp from QuantLib's SobolRsg\n"
        << ";;;; (JoeKuoD6). Do not edit.\n";
    out << "(:dimensions " << dimensions << " :points " << points << "\n :hashes (";
    for (Size d = 0; d < dimensions; ++d) out << (d ? " " : "") << hash[d];
    out << ")\n :first-points (";
    for (Size i = 0; i < 16; ++i) {
        out << "\n  (";
        for (Size d = 0; d < dimensions; ++d) out << (d ? " " : "") << rows[i][d];
        out << ")";
    }
    out << ")\n :first-dimensions (";
    for (Size d = 0; d < 8; ++d) {
        out << "\n  (";
        for (Size i = 0; i < points; ++i) out << (i ? " " : "") << rows[i][d];
        out << ")";
    }
    out << "))\n";
    return 0;
}
